import{z as o,x as s,o as B,c as d,q as t,j as n,D as a,d as e,s as i,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"抵押品与资金链","description":"","frontmatter":{"title":"抵押品与资金链","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-collateral-funding.md","filePath":"quant/rc-collateral-funding.md","lastUpdated":1791063341000}'),c={name:"quant/rc-collateral-funding.md"};function p(D,E,u,C,m,f){const r=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="抵押品与资金链" tabindex="-1">抵押品与资金链 <a class="header-anchor" href="#抵押品与资金链" aria-label="Permalink to &quot;抵押品与资金链&quot;">​</a></h1><div class="epigraph"><p>影子银行以抵押品为货币：2008 年的挤兑没有走存款窗口，它走的是 haircut 与保证金窗口——折价一升，杠杆一夜蒸发。</p><footer>—— 据 Gorton and Metrick, *Journal of Financial Economics*, 2012；Duffie, *Journal of Economic Perspectives*, 2010 整理</footer></div><p><a href="/quant/rc-cds-index-basis">上一课</a>把组合信用落到了可交易的指数与基差上。信用侧还差最后一块地基：所有这些合约的资金面。同一笔现金流，在抵押的利率互换、无抵押贷款与交叉货币互换里有三个不同的折现率；同一批国债，在回购市场里今天是现金、明天是保证金。本课讲抵押品如何定价、如何流转、如何在危机里变成传导链，为下一课的 XVA 联动供料。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2008 年之前教科书用一条 LIBOR 曲线贴现一切；之后市场分裂：抵押的利率互换贴现到 OIS——因为抵押几乎消除了信用暴露，而抵押品本身生息；无抵押暴露按各自资金成本折现；不同币种、不同抵押品类别之间出现持续不归零的基差，见<a href="/quant/multi-curve-ois">OIS 与多曲线</a>与<a href="/quant/xccy-basis">交叉货币基差</a>。缺口是：给定一笔业务，它的资金成本从哪里来——回购利率（GC 与特定券）、折价、保证金期限，如何进入折现与报价；以及危机时这条链如何把价格压力放大成螺旋。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定价规则只有一条：每笔现金流按它的真实资金来源折现。抵押衍生品用 OIS 类曲线；无抵押存量用内部资金转移价格；缺合格抵押品时，「抵押品转型」——把低等级资产换成市场接受的抵押——是真实支出，要进报价。回购侧：GC 利率反映整体现金与抵押的松紧，特定券利差反映个券稀缺，<a href="/quant/implied-repo">隐含回购利率</a>把它与期货定价连起来；折价决定杠杆，\\(2\\%\\) 的折价允许约五十倍杠杆，折价升到 \\(10\\%\\) 杠杆立减到十一倍——杠杆对折价是一阶敏感。保证金期限（MPOR）决定追保通知与处置之间的时间，直接进入 <a href="/quant/mva-initial-margin">MVA 初始保证金调整</a>与 SA-CCR 的公式。机构内部要分清三个账户：交易台的资金、司库的存量与抵押品柜台的可动用券，三者价格与期限都不同，混账会让每笔报价的资金成本都对不上。</p><p><span class="marginnote">折价（haircut）翻译一下：借 100 万，债主要你押 102 万的券，那 2 万差额就是折价——市场对「这券明天可能卖不出好价」收的保险费。折价越高，同一批券能借到的现金越少，能撑的杠杆随之缩水。</span></p><p><span class="marginnote">资金转移价格（FTP）翻译一下：司库像一家「内部银行」，交易台要用无抵押资金，就得按司库公布的内部利率付租。这笔租不写进报价，前台就在免费占用昂贵的资金，报价系统性偏低——很多「赚钱」的盘子和司库一结算就变亏。</span></p>',9)),(B(),n(l,null,{default:a(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CASH%5B%22%E7%8E%B0%E9%87%91%E6%B5%81%22%5D%20--%3E%20SRC%7B%22%E8%B5%84%E9%87%91%E6%9D%A5%E6%BA%90%3F%22%7D%0A%20%20SRC%20--%3E%7C%22%E6%8A%B5%E6%8A%BC%22%7C%20OIS%5B%22OIS%20%E6%9B%B2%E7%BA%BF%E6%8A%98%E7%8E%B0%22%5D%0A%20%20SRC%20--%3E%7C%22%E6%97%A0%E6%8A%B5%E6%8A%BC%22%7C%20FTP%5B%22%E5%86%85%E9%83%A8%E8%B5%84%E9%87%91%E8%BD%AC%E7%A7%BB%E4%BB%B7%22%5D%0A%20%20SRC%20--%3E%7C%22%E9%94%99%E5%B8%81%E7%A7%8D%22%7C%20XC%5B%22%E4%BA%A4%E5%8F%89%E8%B4%A7%E5%B8%81%E5%9F%BA%E5%B7%AE%22%5D%0A%20%20COLL%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E6%9F%9C%E5%8F%B0%22%5D%20--%3E%20REPO%5B%22%E5%9B%9E%E8%B4%AD%EF%BC%9AGC%20%2F%20%E7%89%B9%E5%AE%9A%E5%88%B8%20%2F%20%E6%8A%98%E4%BB%B7%22%5D%0A%20%20REPO%20--%3E%20LEV%5B%22%E6%8A%98%E4%BB%B7%E5%86%B3%E5%AE%9A%E6%9D%A0%E6%9D%86%E5%80%8D%E6%95%B0%22%5D%0A%20%20LEV%20--%3E%20SPIRAL%5B%22%E5%8D%B1%E6%9C%BA%E8%9E%BA%E6%97%8B%EF%BC%9A%E6%8A%98%E4%BB%B7%E4%B8%8E%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E5%8D%87%20%E2%86%92%20%E6%8A%9B%E5%94%AE%20%E2%86%92%20%E5%86%8D%E4%B8%8A%E5%8D%87%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"Gorton 与 Metrick 对 2007 到 2008 年回购市场的测量显示，资产支持证券的回购折价从接近零升到约 \\(45\\%\\)：违约率没有翻几十倍，跳变的是「对抵押品的不信任」这个状态变量——折价与保证金同时上升，杠杆被动收缩，抛售压低抵押品价格，再推高折价。这就是「对回购的挤兑」，也是 2020 年 3 月现金冲刺与 2022 年英国 LDI 事件的同一骨架，本课程最后一课会回放这两个案例。交叉货币基差是这条链的全局价格：美元稀缺时基差走阔，它把全球资金松紧写进每一个远期外汇与债券组合的报价。抵押品条款本身有信用内容：评级下调触发追加抵押的条款，恰在对手方临近困境时吃紧——这是错向风险的抵押版，留给 XVA 课展开。",-1)),(B(),n(l,null,{default:a(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISTRUST%5B%22%E5%AF%B9%E6%8A%B5%E6%8A%BC%E5%93%81%E7%9A%84%E4%B8%8D%E4%BF%A1%E4%BB%BB%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20H%5B%22%E5%9B%9E%E8%B4%AD%E6%8A%98%E4%BB%B7%20h%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20H%20--%3E%20LEV%5B%22%E5%8F%AF%E6%94%AF%E6%92%91%E6%9D%A0%E6%9D%86%E9%AA%A4%E9%99%8D%22%5D%0A%20%20LEV%20--%3E%20SELL%5B%22%E8%A2%AB%E8%BF%AB%E6%8A%9B%E5%94%AE%E6%88%96%E6%97%A0%E6%B3%95%E7%BB%AD%E6%BB%9A%22%5D%0A%20%20SELL%20--%3E%20PRICE%5B%22%E6%8A%B5%E6%8A%BC%E5%93%81%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%22%5D%0A%20%20PRICE%20--%3E%7C%22%E8%9E%BA%E6%97%8B%E8%87%AA%E6%88%91%E5%BC%BA%E5%8C%96%22%7C%20DISTRUST%0A%20%20MPOR%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E6%9C%9F%E9%99%90%20MPOR%20%E6%8B%89%E9%95%BF%22%5D%20--%3E%20H%0A%20%20CB%5B%22%E5%A4%AE%E8%A1%8C%E6%B5%81%E5%8A%A8%E6%80%A7%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20BREAK%5B%22%E4%BB%8E%E5%A4%96%E9%83%A8%E6%B3%A8%E5%85%A5%E7%8E%B0%E9%87%91%E6%89%93%E6%96%AD%E8%9E%BA%E6%97%8B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">交叉货币基差可以想成全球美元的「黑市汇率」：在官方利率之外，大家真金白银换美元时还要额外贴多少。美元一紧张这个贴水立刻走阔，往往比任何官方报告都更早告诉你这个体系里谁缺钱。</span></p><p><span class="marginnote">折价的杠杆公式：名义除以 \\((1-h)\\)。\\(h=2\\%\\) 时约 51 倍，\\(h=10\\%\\) 时 11 倍，\\(h=45\\%\\) 时不足 2 倍——折价从 2% 移到 10%，等于无声地撤掉八成杠杆，不需要任何违约发生。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课讲双边与回购的链，不展开中央对手方的瀑布结构（见<a href="/quant/ccp-default-waterfall">CCP 违约瀑布</a>）与清算会员的连带责任。内部资金转移定价的治理——哪个部门承担流动性成本、存款是否补贴贷款——是银行管理会计，不进本课。流动性监管（覆盖率与稳定资金比例）持续抬高优质抵押的需求与基差，属监管资本课的相邻主题，这里只承认其存在。「抵押品中性」的假设在流动性分层的市场里不成立：国债、机构债、公司债、股票作为抵押的能力不同，账面上同为现金等价物的资产，在压力时刻的价格并不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>折现曲线跟着资金来源走：抵押用 OIS，无抵押用 FTP，错币种吃基差；一条曲线贴一切的时代结束了。</li><li>回购折价决定杠杆倍数，折价上升是被动的无声去杠杆。</li><li>基差是资金稀缺的价格：交叉货币基差把全球美元松紧写进所有报价。</li><li>折价与保证金的顺周期上升构成挤兑螺旋，是 2008、2020、2022 三次危机的共同机制。</li><li>出处：Gorton and Metrick, <em>Journal of Financial Economics</em>, 2012；Duffie, <em>Journal of Economic Perspectives</em>, 2010；多曲线与 MVA 见本栏相应课程。</li></ul>',6))])}const F=o(c,[["render",p]]);export{S as __pageData,F as default};
